"""Modul tambahan agar Flutter, Android (Compose), dan Kotlin mencakup topik roadmap.sh (flutter, android, kotlin).
Ditambahkan di akhir jalur supaya alamat pelajaran yang sudah ada tidak bergeser."""
from mobile_lib import C, M, q
from mobile_dart_x import S


def D(soal, petunjuk, jawab, out=None):
    return S(soal, petunjuk, jawab, out, lang='dart')


def K(soal, petunjuk, jawab, out=None):
    return S(soal, petunjuk, jawab, out, lang='kotlin')


